<?php
declare(strict_types=1);
return static function(PDO$pdo):void{
 $pdo->exec("CREATE TABLE program_course_clos(id INT AUTO_INCREMENT PRIMARY KEY,program_specification_id INT NOT NULL,program_course_id INT NOT NULL,clo_code VARCHAR(30) NOT NULL,clo_domain VARCHAR(100) NULL,clo_text TEXT NOT NULL,display_order INT NOT NULL DEFAULT 0,created_by_user_id INT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_program_course_clo(program_course_id,clo_code),KEY idx_program_clo_program(program_specification_id),CONSTRAINT fk_program_clo_program FOREIGN KEY(program_specification_id) REFERENCES program_specifications(id) ON DELETE CASCADE,CONSTRAINT fk_program_clo_course FOREIGN KEY(program_course_id) REFERENCES program_specification_courses(id) ON DELETE CASCADE,CONSTRAINT fk_program_clo_creator FOREIGN KEY(created_by_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $pdo->exec("CREATE TABLE program_plo_clo_matrix(id INT AUTO_INCREMENT PRIMARY KEY,program_specification_id INT NOT NULL,clo_id INT NOT NULL,plo_id INT NOT NULL,alignment_level ENUM('Supporting','Primary') NOT NULL DEFAULT 'Supporting',notes VARCHAR(500) NULL,created_by_user_id INT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_program_plo_clo(clo_id,plo_id),KEY idx_matrix_program(program_specification_id),CONSTRAINT fk_matrix_program FOREIGN KEY(program_specification_id) REFERENCES program_specifications(id) ON DELETE CASCADE,CONSTRAINT fk_matrix_clo FOREIGN KEY(clo_id) REFERENCES program_course_clos(id) ON DELETE CASCADE,CONSTRAINT fk_matrix_plo FOREIGN KEY(plo_id) REFERENCES program_specification_plos(id) ON DELETE CASCADE,CONSTRAINT fk_matrix_creator FOREIGN KEY(created_by_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
};
